VOWELS = "aeiou"


def _translate_word(word):
    # Rule 1: word starts with a vowel, or with "xr" or "yt"
    if word[0] in VOWELS or word.startswith(("xr", "yt")):
        return word + "ay"

    # Find where the leading consonant cluster ends:
    # at the first vowel, or at a "y" that is not the first letter
    # (Rules 2 and 4).
    i = 0
    while i < len(word) and word[i] not in VOWELS and word[i] != "y":
        i += 1
    if i == 0:  # word starts with "y" -> treat as consonant
        i = 1

    # Rule 3: if the cluster is followed by "qu", move the "qu" too
    if word[i:i + 2] == "qu":
        i += 2

    return word[i:] + word[:i] + "ay"


def translate(text):
    return " ".join(_translate_word(word) for word in text.split(" "))

